async function click(cdp, point) { await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: point.x, y: point.y, button: "left", clickCount: 1 }); await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: point.x, y: point.y, button: "left", clickCount: 1 }); }
async function touch(cdp, type, x, y) { await cdp.send("Input.dispatchTouchEvent", { type, touchPoints: ["touchEnd", "touchCancel"].includes(type) ? [] : [{ x, y, id: 1, radiusX: 5, radiusY: 5, force: 1 }] }); await delay(45); }
async function touches(cdp, type, points) { await cdp.send("Input.dispatchTouchEvent", { type, touchPoints: points.map(([x, y, id]) => ({ x, y, id, radiusX: 5, radiusY: 5, force: 1 })) }); await delay(45); }
async function navigate(cdp, url) { await cdp.send("Page.navigate", { url }); for (let i = 0; i < 100; i += 1) { if (await evaluate(cdp, `Boolean(document.getElementById('activity')?.contentWindow?.__kinematicsQuantitativeDebug)`)) return; await delay(50); } throw new Error("activity did not load in iframe"); }
async function resetMobileTouchViewport(cdp) { await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }); await cdp.send("Emulation.clearDeviceMetricsOverride"); await cdp.send("Emulation.setDeviceMetricsOverride", { width: 390, height: 600, deviceScaleFactor: 1, mobile: true }); await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 2 }); }
async function settleHostScroll(cdp, target, label) { const settled = await evaluate(cdp, `new Promise((resolve, reject) => { let stable=0, frames=0; const tick=() => { window.scrollTo(0, ${target}); const now=Math.round(window.scrollY); stable=now === ${target} ? stable + 1 : 0; if (stable >= 5) return resolve(now); if (++frames > 60) return reject(new Error('host scroll did not settle')); requestAnimationFrame(tick); }; requestAnimationFrame(tick); })`); assert.equal(settled, target, `${label}: host scroll settles before the next trusted touch`); }
async function settlePanelScroll(cdp, target, label) { const settled = await evaluate(cdp, `new Promise((resolve, reject) => { const panel=document.getElementById('activity').contentWindow.document.getElementById('controlsPanel'); let stable=0,frames=0; const tick=() => { panel.scrollTop=${target}; const now=Math.round(panel.scrollTop); stable=now === ${target} ? stable + 1 : 0; if (stable >= 5) return resolve(now); if (++frames > 60) return reject(new Error('panel scroll did not settle')); requestAnimationFrame(tick); }; requestAnimationFrame(tick); })`); assert.equal(settled, target, `${label}: panel scroll settles before the multi-contact rows`); }
